# Dict comprehension
names = ['Alice', 'Bob', 'Charlie']
scores = [95, 82, 78]

# zip + dict comprehension
score_map = {name: score for name, score in zip(names, scores)}
print(score_map)   # {'Alice': 95, 'Bob': 82, 'Charlie': 78}

# Invert a dict
original = {'a': 1, 'b': 2, 'c': 3}
inverted = {v: k for k, v in original.items()}
print(inverted)    # {1: 'a', 2: 'b', 3: 'c'}

# Filter a dict (keep high scorers)
high = {name: score for name, score in score_map.items() if score > 80}
print(high)        # {'Alice': 95, 'Bob': 82}


# Generator expression — lazy, memory-efficient
total = sum(n**2 for n in range(1, 1001))   # no list created!
print(total)       # 333833500

big_nums = (n for n in range(10_000_000) if n % 1_000_000 == 0)
for n in big_nums:
    print(n)       # 0, 1000000, 2000000, ... (lazy — no 10M list)

# any() / all() with generators — short-circuit
nums = [2, 4, 6, 8, 9]
print(any(n % 2 != 0 for n in nums))   # True (9 is odd)
print(all(n > 0 for n in nums))        # True
